from pathlib import Pathimport osimport jsonimport requestsimport pandas as pdimport numpy as npimport matplotlib.pyplot as plt# PathPROJECT_ROOT = Path(__file__).resolve().parent.parentRAW_DATA_DIR = PROJECT_ROOT / "data" / "raw"PROCESSED_DIR = PROJECT_ROOT / "data" / "processed"FIGURES_DIR = PROJECT_ROOT / "figures"for folder in [RAW_DATA_DIR, PROCESSED_DIR, FIGURES_DIR]:    folder.mkdir(parents=True, exist_ok=True)RAW_FILE = RAW_DATA_DIR / "cirbe_2024_gp_history.json"DAILY_FILE = PROCESSED_DIR / "cirbe_2024_daily_altitude.csv"FIGURE_FILE = FIGURES_DIR / "cirbe_2024_altitude.png"# Load CIRBE orbital datadef load_orbital_history():    print("Loading CIRBE orbital history...")    if not RAW_FILE.exists():        raise FileNotFoundError(            f"Could not find {RAW_FILE}\n"            "Run download_cirbe_2024.py first."        )    with open(        RAW_FILE,        "r",        encoding="utf-8",    ) as file:        records = json.load(file)    print(        f"Loaded {len(records)} CIRBE orbital records."    )    return recordsdef calculate_altitude(records):    df = pd.DataFrame(records)    df["EPOCH"] = pd.to_datetime(        df["EPOCH"],        utc=True,        errors="coerce",    )    df["MEAN_MOTION"] = pd.to_numeric(        df["MEAN_MOTION"],        errors="coerce",    )    df = df.dropna(subset=["EPOCH", "MEAN_MOTION"])    df = df[df["MEAN_MOTION"] > 0].copy()    df = df.sort_values("EPOCH")    if df.empty:        raise ValueError("No usable orbital records.")    # Earth's gravitational parameter (km^3/s^2)    mu = 398600.4418    # Earth's mean radius (km)    R_earth = 6371.0    # Convert revolutions/day to radians/second    df["n_rad_s"] = (        df["MEAN_MOTION"] * 2 * np.pi / 86400    )    # Kepler's third law    df["semi_major_axis_km"] = (        mu / df["n_rad_s"]**2    ) ** (1 / 3)    # Approximate mean orbital altitude    df["altitude_km"] = (        df["semi_major_axis_km"] - R_earth    )    # Group observations by UTC day    df["date"] = df["EPOCH"].dt.floor("D")    daily = (        df.groupby("date")["altitude_km"]        .median()        .reset_index()    )    daily.to_csv(DAILY_FILE, index=False)    print(f"\nSaved daily altitude: {DAILY_FILE}")    print("\nFirst five observations:")    print(daily.head())    return dailydef calculate_orbital_decay(daily):    daily = daily.sort_values("date").copy()    # Time between consecutive observations    daily["time_difference_days"] = (        daily["date"].diff().dt.total_seconds() / 86400    )    # Change in altitude    daily["altitude_change_km"] = (        daily["altitude_km"].diff()    )    # Positive = altitude loss    daily["orbital_decay_km_day"] = (        -daily["altitude_change_km"]        / daily["time_difference_days"]    )    # Define comparison periods    dates = daily["date"].dt.strftime("%Y-%m-%d")    before = daily[        (dates >= "2024-05-01")        & (dates <= "2024-05-09")    ]    storm = daily[        (dates >= "2024-05-10")        & (dates <= "2024-05-12")    ]    after = daily[        (dates >= "2024-05-13")        & (dates <= "2024-05-21")    ]    for name, period in [        ("Before storm", before),        ("During storm", storm),        ("After storm", after),    ]:        print(            f"{name}: "            f"{period['orbital_decay_km_day'].mean():.4f} km/day"        )    # Save results    output_file = (        PROCESSED_DIR / "cirbe_2024_daily_decay.csv"    )    daily.to_csv(output_file, index=False)    print(f"\nSaved decay data to: {output_file}")    return daily# Plot CIRBE orbital altitudedef plot_altitude(daily):    plt.figure(figsize=(11, 6))    plt.plot(        daily["date"],        daily["altitude_km"],        color="navy",        linewidth=1.8,        label="CIRBE approximate mean altitude",    )    storm_start = pd.Timestamp(        "2024-05-10", tz="UTC"    )    storm_end = pd.Timestamp(        "2024-05-13", tz="UTC"    )    plt.axvspan(        storm_start,        storm_end,        color="red",        alpha=0.2,        label="May 10-12 geomagnetic storm",    )    plt.xlabel("Date")    plt.ylabel("Approximate Mean Orbital Altitude (km)")    plt.title(        "CIRBE Orbital Altitude: April-June 2024"    )    plt.legend()    plt.grid(alpha=0.3)    plt.tight_layout()    plt.savefig(        FIGURE_FILE,        dpi=300,        bbox_inches="tight",    )    print(f"\nSaved figure: {FIGURE_FILE}")    plt.show()# Maindef main():    records = load_orbital_history()    daily = calculate_altitude(records)    daily = calculate_orbital_decay(daily)    plot_altitude(daily)    print("\nCIRBE analysis complete!")if __name__ == "__main__":    main()